using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using Monja;
class ExcelIntegration {
 static int exit=1;static List<string> checks=new List<string>();static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add(label);Console.WriteLine("PASS "+label);}
 [STAThread]static int Main(){SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());var timer=new System.Windows.Forms.Timer{Interval=20};timer.Tick+=async(s,e)=>{timer.Stop();try{await Run();exit=0;}catch(Exception ex){Console.WriteLine("FAIL "+ex.GetType().FullName+" "+ex.Message+" "+ex.StackTrace);}finally{System.Windows.Forms.Application.ExitThread();}};timer.Start();System.Windows.Forms.Application.Run();return exit;}
 static async Task Run(){dynamic app=null,books=null,book=null,other=null,sheets=null,sheet=null,summary=null;try{
  app=Activator.CreateInstance(Type.GetTypeFromProgID("Excel.Application"));app.Visible=false;app.DisplayAlerts=false;books=app.Workbooks;book=books.Add();sheets=book.Worksheets;sheet=sheets.Item[1];sheet.Name="入力";summary=sheets.Add(Type.Missing,sheet);summary.Name="集計";
  dynamic data=null,formula=null;try{data=sheet.Range["A1:B4"];data.Value2=new object[,]{{"Category","Amount"},{"A",10},{"B",20},{"A",30}};formula=summary.Range["D10"];formula.Formula="=SUM('入力'!B2:B4)";}finally{ExcelScanner.Release((object)formula);ExcelScanner.Release((object)data);}
  dynamic charts=null,obj=null,chart=null,series=null,item=null;try{charts=summary.ChartObjects();obj=charts.Add(100,40,350,200);obj.Name="売上グラフ";chart=obj.Chart;series=chart.SeriesCollection();item=series.NewSeries();item.Formula="=SERIES(\"Sales\",入力!A2:A4,入力!B2:B4,1)";}finally{ExcelScanner.Release((object)item);ExcelScanner.Release((object)series);ExcelScanner.Release((object)chart);ExcelScanner.Release((object)obj);ExcelScanner.Release((object)charts);}
  dynamic caches=null,cache=null,dest=null,pt=null;try{caches=book.PivotCaches();cache=caches.Create(1,"'入力'!R1C1:R4C2");dest=summary.Range["H5"];pt=cache.CreatePivotTable(dest,"売上ピボット");}finally{ExcelScanner.Release((object)pt);ExcelScanner.Release((object)dest);ExcelScanner.Release((object)cache);ExcelScanner.Release((object)caches);}
  dynamic chartSheets=null,chartSheet=null,chartSeries=null,chartSeriesItem=null;try{chartSheets=book.Charts;chartSheet=chartSheets.Add();chartSheet.Name="専用グラフ";chartSeries=chartSheet.SeriesCollection();chartSeriesItem=chartSeries.NewSeries();chartSeriesItem.Formula="=SERIES(\"Sales\",入力!A2:A4,入力!B2:B4,1)";}finally{ExcelScanner.Release((object)chartSeriesItem);ExcelScanner.Release((object)chartSeries);ExcelScanner.Release((object)chartSheet);ExcelScanner.Release((object)chartSheets);}
  other=books.Add();dynamic os=null,or=null;try{os=other.Worksheets.Item[1];or=os.Range["A1"];or.Formula="='["+book.Name+"]入力'!B2";}finally{ExcelScanner.Release((object)or);ExcelScanner.Release((object)os);}
  dynamic sharedCache=null,table=null,tableCache=null;
  try{Console.WriteLine("Construct shared pivots");sharedCache=book.PivotCaches().Item(1);for(int i=0;i<12;i++){dynamic copy=sharedCache.CreatePivotTable(summary.Range["H"+(100+i*100)],"SharedPivot"+i);ExcelScanner.Release((object)copy);}Console.WriteLine("Construct table");table=sheet.ListObjects.Add(1,sheet.Range["A1:B4"],Type.Missing,1);table.Name="TraceSales";Console.WriteLine("Construct table pivot");tableCache=book.PivotCaches().Create(1,"TraceSales");dynamic tablePivot=tableCache.CreatePivotTable(summary.Range["T100"],"TablePivot");ExcelScanner.Release((object)tablePivot);}finally{ExcelScanner.Release((object)tableCache);ExcelScanner.Release((object)table);ExcelScanner.Release((object)sharedCache);}
  book.Activate();dynamic batchSheet=sheets.Add();batchSheet.Name="グラフ検証";batchSheet.Activate();Console.WriteLine("Construct chart batch");dynamic manyCharts=batchSheet.ChartObjects();try{for(int i=0;i<30;i++){dynamic extra=manyCharts.Add(100,260+i*20,300,180),extraChart=extra.Chart,extraSeries=extraChart.SeriesCollection(),extraItem=extraSeries.NewSeries();extra.Name="ChartBatch"+i;extraItem.Formula="=SERIES(\"Sales\",入力!A2:A4,入力!B2:B4,1)";ExcelScanner.Release((object)extraItem);ExcelScanner.Release((object)extraSeries);ExcelScanner.Release((object)extraChart);ExcelScanner.Release((object)extra);}}finally{ExcelScanner.Release((object)manyCharts);}
  var targets=new HashSet<string>{ExcelScanner.Identity(book),ExcelScanner.Identity(other)};var result=await new ExcelScanner((object)app).Scan(targets,false,CancellationToken.None,new Progress<string>(s=>Console.WriteLine(s)));
  Check(result.Edges.Any(e=>e.Kind=="formula"&&e.Source.Sheet=="入力"&&e.Source.Address=="B2:B4"),"live formula range");Check(result.Edges.Any(e=>e.Kind=="chart"&&e.Target.Name=="売上グラフ"),"live embedded chart");Check(result.Edges.Any(e=>e.Kind=="pivot"&&e.Target.Address=="H5"&&e.Source.Address=="A1:B4"),"live pivot source");Check(result.Edges.Any(e=>e.Kind=="formula"&&e.Target.Book==ExcelScanner.Identity(other)),"multiple workbook traversal");Check(result.Edges.Any(e=>e.Kind=="chart"&&e.Target.Sheet=="専用グラフ"&&e.Target.Address==null),"live chart sheet");
  Check(result.Edges.Count(e=>e.Kind=="pivot"&&e.Target.Name.StartsWith("SharedPivot"))==12,"shared pivot cache represented per pivot");Check(result.Edges.Any(e=>e.Kind=="pivot"&&e.Target.Name=="TablePivot"&&e.Source.Address=="A1:B4"),"live table pivot source");Check(result.Edges.Where(e=>e.Kind=="chart"&&e.Target.Name.StartsWith("ChartBatch")).Select(e=>e.Target.Name).Distinct().Count()==30,"30 live embedded charts");
  using(var cancel=new CancellationTokenSource()){cancel.Cancel();bool stopped=false;try{await new ExcelScanner((object)app).Scan(targets,false,cancel.Token,new Progress<string>());}catch(OperationCanceledException){stopped=true;}Check(stopped,"scan cancellation");}
  Console.WriteLine("Diagnostics: "+String.Join(" | ",result.Diagnostics));
  string destFolder=Path.GetFullPath("test-workbooks");Directory.CreateDirectory(destFolder);Console.WriteLine("Saving fixture");book.SaveCopyAs(Path.Combine(destFolder,"integration-"+DateTime.Now.ToString("HHmmss")+".xlsx"));Console.WriteLine("Fixture saved");
 }finally{Console.WriteLine("Closing isolated Excel instance");Cleanup(()=>{if(other!=null)other.Close(false);});Cleanup(()=>{if(book!=null)book.Close(false);});Cleanup(()=>{if(app!=null)app.Quit();});ExcelScanner.Release((object)summary);ExcelScanner.Release((object)sheet);ExcelScanner.Release((object)sheets);ExcelScanner.Release((object)other);ExcelScanner.Release((object)book);ExcelScanner.Release((object)books);ExcelScanner.Release((object)app);}}
 static void Cleanup(Action action){try{action();}catch(System.Runtime.InteropServices.COMException ex){Console.WriteLine("Cleanup HRESULT: "+ex.ErrorCode.ToString("X"));}}
}


